// Entrada: lista de carpetas
const folders = $input.all().map(i => i.json);
if (!folders.length) {
  return [{ json: { error: "❌ No hay carpetas para procesar" } }];
}

// Devuelve un item para cada carpeta, incluyendo su endpoint de consulta
return folders.map(folder => ({
  json: {
    id: folder.id,
    name: folder.name,
    url: `https://graph.microsoft.com/v1.0/drives/b!hdBF9ZToCEywbf2VWek5HwI3e2ufJmtOijEE_7__8_2AJjaObVPEQ4HWyHOHmaCe/items/${folder.id}/children?$select=id,name,webUrl,parentReference,lastModifiedDateTime&$top=50`
  }
}));

// Extrae el archivo más reciente de cada respuesta
const items = $input.all();
const results = [];

for (const item of items) {
  const files = item.json.value || [];
  if (files.length > 0) {
    // Ordenar por fecha y tomar el más reciente
    const latest = files.reduce((a, b) => {
      return new Date(a.lastModifiedDateTime) > new Date(b.lastModifiedDateTime) ? a : b;
    });

    results.push({
      json: {
        name: latest.name,
        id: latest.id,
        lastModifiedDateTime: latest.lastModifiedDateTime,
        webUrl: latest.webUrl,
        parentPath: latest.parentReference?.path || "",
        siteId: latest.parentReference?.siteId || "",
        driveId: latest.parentReference?.driveId || ""
      }
    });
  }
}

return results;

// === Combina todos los archivos y encuentra el más reciente globalmente ===
const all = $input.all().map(i => i.json).filter(f => f.lastModifiedDateTime);

if (!all.length) {
  return [{ json: { message: "No se recibieron archivos para comparar" } }];
}

// Ordena por fecha descendente
all.sort((a, b) => new Date(b.lastModifiedDateTime) - new Date(a.lastModifiedDateTime));

// Toma el más reciente
const latest = all[0];

// Extrae el nombre de la carpeta contenedora
const parentName =
  latest.parentReference?.name ||
  latest.parentFolder ||
  (latest.parentPath?.split("/")?.pop() ?? null) ||
  null;

console.log(`✅ Archivo más reciente encontrado: ${latest.name}`);
console.log(`📁 Carpeta contenedora: ${parentName}`);
console.log(`📁 Total de carpetas comparadas: ${all.length}`);

return [{
  json: {
    id: latest.id,
    name: latest.name,
    lastModifiedDateTime: latest.lastModifiedDateTime,
    webUrl: latest.webUrl,
    parentFolder: parentName,
    parentPath: latest.parentPath || latest.parentReference?.path || null,
    driveId: latest.driveId || latest.parentReference?.driveId || null,
    totalCompared: all.length
  }
}];

const folders = $input.item.json.value || [];

if (!folders.length) {
  throw new Error("❌ No se encontraron subcarpetas en SOPORTE ESTRUCTURADO");
}

console.log(`✅ Se encontraron ${folders.length} subcarpetas para escanear`);

return folders.map(folder => ({
  json: {
    id: folder.id,
    name: folder.name
  }
}));

// === FILTRAR LOADER POR PARENTFOLDER O CREAR UNO NUEVO ===
const fileData = $('Seleccionar El Más Reciente').item.json;
const parentFolder = (fileData.parentFolder || '').toString().trim();
const flowiseResponse = $input.item.json;

// Validar y extraer el array de stores
let documentStores = [];

if (Array.isArray(flowiseResponse)) {
  documentStores = flowiseResponse;
} else if (flowiseResponse.data && Array.isArray(flowiseResponse.data)) {
  documentStores = flowiseResponse.data;
} else if (flowiseResponse.stores && Array.isArray(flowiseResponse.stores)) {
  documentStores = flowiseResponse.stores;
} else {
  documentStores = [flowiseResponse];
}

const s3Path = `knowledge/support/${parentFolder}/${fileData.name}`;
const flowiseBaseUrl = "https://mobilvendor-ai.com/api/v1/document-store/upsert";
const normalizedParent = parentFolder.toLowerCase().trim();

// Buscar el Document Store que tiene un loader con nombre igual al parentFolder
let targetStore = null;
let targetLoader = null;

for (const store of documentStores) {
  if (store.loaders && Array.isArray(store.loaders)) {
    const matchingLoader = store.loaders.find(loader => {
      const loaderName = loader.loadername || loader.loaderName || loader.name || '';
      return loaderName.toLowerCase().trim() === normalizedParent;
    });

    if (matchingLoader) {
      targetStore = store;
      targetLoader = matchingLoader;
      break;
    }
  }
}

// Si NO se encontró, usar storeId fijo y crear nuevo loader
if (!targetStore || !targetLoader) {
  return [{
    json: {
      storeId: "3a92cc47-3ffc-40f8-ac68-e4fbf79510ce",
      storeName: "kb_support_s3",
      docId: null,
      loaderName: normalizedParent,
      parentFolder,
      fileName: fileData.name,
      lastModified: fileData.lastModifiedDateTime,
      s3Path: s3Path,
      webUrl: fileData.webUrl,
      flowiseUrl: `${flowiseBaseUrl}/3a92cc47-3ffc-40f8-ac68-e4fbf79510ce`,
      isNewLoader: true,
      payload: {
        loaderName: normalizedParent,
        metadata: JSON.stringify({
          fileName: fileData.name,
          parentFolder: parentFolder,
          lastModified: fileData.lastModifiedDateTime,
          s3Path: s3Path,
          webUrl: fileData.webUrl,
          source: "SharePoint-S3-Backup",
          uploadedAt: new Date().toISOString()
        }),
        replaceExisting: false,
        loader: {
          name: "s3Directory",
          config: {
            bucketName: "mobilvendorzei",
            region: "us-east-1",
            prefix: `knowledge/support/${parentFolder}/K`,
            pdfUsage: "perPage",
            FLOWISE_CREDENTIAL_ID: "428fecca-bb72-4d17-9894-0fe218c91985"
          }
        },
        splitter: {
          config: {
            chunkSize: 20000,
            chunkOverlap: 400
          }
        }
      }
    }
  }];
}

// Si SÍ se encontró, usar SOLO config BASE fija (ignorar loaderConfig original)
return [{
  json: {
    storeId: targetStore.id,
    storeName: targetStore.name,
    docId: targetLoader.id,
    loaderName: targetLoader.loadername || targetLoader.loaderName || targetLoader.name,
    parentFolder: parentFolder,
    fileName: fileData.name,
    lastModified: fileData.lastModifiedDateTime,
    s3Path: s3Path,
    webUrl: fileData.webUrl,
    flowiseUrl: `${flowiseBaseUrl}/${targetStore.id}`,
    isNewLoader: false,
    payload: {
      docId: targetLoader.id,
      loaderName: targetLoader.loadername || targetLoader.loaderName || targetLoader.name,
      metadata: JSON.stringify({
        fileName: fileData.name,
        parentFolder: parentFolder,
        lastModified: fileData.lastModifiedDateTime,
        s3Path: s3Path,
        webUrl: fileData.webUrl,
        source: "SharePoint-S3-Backup",
        uploadedAt: new Date().toISOString()
      }),
      replaceExisting: true,
      loader: {
        name: targetLoader.loaderId,
        config: {
          bucketName: "mobilvendorzei",
          region: "us-east-1",
          prefix: `knowledge/support/${parentFolder}/K`,
          pdfUsage: "perPage",
